<?php $title='Ruang Belajar';$page='learning';$pdo=Database::connection();$u=current_user();$q=$pdo->prepare('SELECT m.*,c.name class_name,s.name subject_name FROM modules m JOIN classes c ON c.id=m.class_id JOIN subjects s ON s.id=m.subject_id WHERE c.name=? AND m.status="active" ORDER BY m.created_at DESC');$q->execute([$u['class_name']]);$rows=$q->fetchAll();require __DIR__.'/../_dashboard_start.php'; ?>
<div class="page-heading"><div><h1>Ruang Belajar</h1><p>Materi pembelajaran sesuai kelas Anda.</p></div></div><div class="card-grid"><?php foreach($rows as $m): ?><article class="course-card"><div class="course-icon"><i class="fa-solid fa-server"></i></div><span><?= e($m['class_name']) ?> · <?= e($m['subject_name']) ?></span><h3><?= e($m['title']) ?></h3><p><?= e($m['description']) ?></p><?php $q=$pdo->prepare('SELECT * FROM materials WHERE module_id=? ORDER BY id');$q->execute([$m['id']]);foreach($q->fetchAll() as $mat): ?><div class="material-item"><b><?= e($mat['title']) ?></b><p><?= nl2br(e($mat['content'])) ?></p><?php if($mat['video_url']): ?><a target="_blank" rel="noopener" href="<?= e($mat['video_url']) ?>">Tonton video <i class="fa-solid fa-play"></i></a><?php endif; ?></div><?php endforeach; ?></article><?php endforeach; ?></div><?php if(!$rows): ?><section class="panel empty-state">Belum ada modul untuk kelas Anda.</section><?php endif; ?><?php require __DIR__.'/../_dashboard_end.php'; ?>